mapper.insert:
MERGE INTO ODS_SALES_BUDGET_FILL_DAILY target USING (
SELECT #{item.regionLevel1} AS region_level1, #{item.regionLevel2} AS region_level2, #{item.channelProperty} AS channel_property, #{item.channelDef} AS channel_def, #{item.storeName} AS store_name, #{item.brandName} AS brand_name, #{item.monthlyName} AS monthly_name, #{item.budgetDtm} AS budget_dtm, #{item.budgetAmount} AS budget_amount, #{item.businessType} AS business_type, #{item.businessProperty} AS business_property, #{item.salesType} AS sales_type FROM dual
) source ON (target.store_name = source.store_name AND target.brand_name = source.brand_name AND target.budget_dtm = source.budget_dtm) WHEN MATCHED THEN UPDATE SET target.region_level1 = source.region_level1, target.region_level2 = source.region_level2, target.channel_property = source.channel_property, target.channel_def = source.channel_def, target.monthly_name = source.monthly_name, target.budget_amount = source.budget_amount, target.business_type = source.business_type, target.business_property = source.business_property, target.sales_type = source.sales_type WHEN NOT MATCHED THEN INSERT (region_level1, region_level2, channel_property, channel_def, store_name, brand_name, monthly_name, budget_dtm, budget_amount, business_type, business_property, sales_type) VALUES (source.region_level1, source.region_level2, source.channel_property, source.channel_def, source.store_name, source.brand_name, source.monthly_name, source.budget_dtm, source.budget_amount, source.business_type, source.business_property, source.sales_type)
